struct Effectivity {
  std::chrono::year_month_day from;
  std::optional<std::chrono::year_month_day> until;   // empty = until further notice

  bool contains(std::chrono::year_month_day asOf) const {
    return asOf >= from && (!until || asOf < *until);  // half-open [from, until)
  }
};

